mapper.select:
select

from ord_dis_presale_order where store_code = #{storeCode}

    and status = #{status}


    and date_format(create_time, '%Y-%m') = #{createMonth}

and is_delete = 0 order by id desc

select
po.id, po.presale_order_no, po.status, po.store_code, po.store_name, po.total_sku_qty, po.total_goods_qty, po.total_order_amount,
po.total_discount_amount,
po.total_pay_amount,  po.pay_time,po.creator,po.org_code,po.biz_org_code, po.create_time, po.updater,
po.update_time, po.is_delete
from ord_dis_presale_order po
inner join ord_dis_presale_order_detail d on d.presale_order_id = po.id
where 1 = 1

    and po.store_code in

        #{item}



    and po.store_code = #{storeCode}


    and po.presale_order_no = #{presaleOrderNo}


    and po.status = #{status}


    and d.goods_code = #{goodsCode}


  and po.create_time between #{beginCreateTime} and #{endCreateTime}


    and po.biz_org_code = #{bizOrgCode}

and po.is_delete = 0 GROUP BY po.id order by po.id desc
